import { getBallotVerification, type GetBallotVerificationData } from '~/client';

export const useBallotDrafts = defineQuery(() => {
  const route = useRoute();
  const { isCanvasserOrSubCanvasser, isManager, userData } = useUserRole();
  const projectId = computed(() => (route.query.project_id as string) || '');
  const canvasserId = computed(() => {
    if (isCanvasserOrSubCanvasser.value && userData.value) {
      return userData.value.id;
    } else {
      return (route.query.canvasser_id as string) || '';
    }
  });
  const isUploadOnCanvassersBehalf = computed(() => {
    return isManager.value && (route.query.is_upload_on_canvassers_behalf as string) === 'true';
  });

  const { data, error, isLoading, refetch } = useQuery({
    key: () => ['ballots.list.draft', projectId.value, canvasserId.value],
    query: () =>
      getBallotVerification({
        composable: '$fetch',
        query: { project_id: projectId.value, canvasser_id: canvasserId.value },
      }),
    enabled: () => !!projectId.value && !!canvasserId.value,
    staleTime: 0,
  });

  return {
    projectId,
    canvasserId,
    isUploadOnCanvassersBehalf,
    ballots: computed(() => data.value?.ballots || []),
    canSubmit: computed(() => data.value?.can_submit || false),
    error,
    isLoading,
    refetch,
  };
});
