import { addNewBallot } from '~/client';
import type { AddBallotRequest } from '~/client';

export const useAddBallot = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: AddBallotRequest) =>
      addNewBallot({
        composable: '$fetch',
        body: data,
      }),
    onSuccess: async (data, requestData) => {
      const queryCache = useQueryCache();
      queryCache.setQueryData(['ballots.list.draft', requestData.project_id, requestData.canvasser_id], () => {
        return data;
      });
      showToastSuccess(`New petition added successfully`);
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    addNewBallot: mutateAsync,
    isAddNewBallotLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
